import subprocess, binascii, re, sys, os, json, textwrap

def get_payload(frame):
    cmd = f'tshark -r /challenge/capture.pcap -Y "frame.number=={frame}" -T fields -e tcp.payload'
    res = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    hexdata = res.stdout.strip()
    if not hexdata:
        return b''
    # hex may contain spaces
    hexdata = hexdata.replace(' ', '')
    try:
        return binascii.unhexlify(hexdata)
    except Exception as e:
        return b''

frames = list(range(25,39)) + [257]
payloads = {}
for f in frames:
    payloads[f] = get_payload(f)
    # print length
    print(f'Frame {f} payload length {len(payloads[f])}')
    # extract printable strings of length >=4
    s = re.findall(r'[A-Za-z0-9+/=]{4,}', payloads[f].decode('latin1', errors='ignore'))
    if s:
        print(' strings:', s)

# Also gather strings from frame 257
print('Done')

